config.script:
// A0 "armar_pedido_carteirinha" (H6 fluxo-ideal#671) — agente tipo `script`. Comportamento = ESTE roteiro (DADO).
// Quando o pedido de carteirinha sai pelo WhatsApp (modelo `pedido_carteirinha_convenio`, H4 #2419), passa
// a acompanhar a conversa: inscreve o leitor (A1) como observador, guardando o item da venda do pedido.
//
// Injetados: event ({subject, payload_safe}), config ({observar_agente, ttl_seg}), call(), log().
//   O pedido referencia o ITEM da venda (referencia_tipo = venda_item); o convênio sai dele no A1.

var subj = event.subject || {};
var p = event.payload_safe || {};
var conversaId = subj.conversa_id || p.conversa_id;
var itemId = subj.referencia_id || p.referencia_id;
var refTipo = p.referencia_tipo || subj.referencia_tipo;

if (!conversaId) { log('pedido enviado sem conversa_id — nada a acompanhar'); return { status: 'sem_conversa' }; }
if (!itemId || (refTipo && refTipo !== 'venda_item')) {
  log('pedido enviado sem o item da venda — nada a acompanhar');
  return { status: 'sem_item' };
}
if (!config.observar_agente) throw new Error("config obrigatória ausente: 'observar_agente'");

var inscricao = {
  conversa_id: String(conversaId),
  observador_tipo: 'bot',
  observador_id: config.observar_agente,
  origem: 'automacao',
  contexto: { venda_item_id: String(itemId) }
};
var ttlSeg = Number(config.ttl_seg) || 0;
if (ttlSeg > 0) inscricao.expira_em = new Date(Date.now() + ttlSeg * 1000).toISOString();

var r = call('inscrever_observador', inscricao);
if (r && r.ok === false) throw new Error('não consegui acompanhar a conversa: HTTP ' + r.status_code);
log('leitor da carteirinha acompanhando a conversa');
return { status: 'armado', conversa_id: String(conversaId), ttl_seg: ttlSeg };

// A1 "ler_carteirinha" (H6 fluxo-ideal#671) — agente tipo `script`. Comportamento = ESTE roteiro (DADO).
// O paciente respondeu ao pedido de carteirinha. Lê as mensagens novas dele (foto ou texto), extrai os dados
// pela MESMA leitura do botão "Extrair carteirinha" (foto → agente de visão; texto → agente de texto deste
// time) e cria uma SOLICITAÇÃO de convênio para a recepção aprovar — nunca grava direto no cadastro.
// Não entendeu → não grava nada e passa a conversa para a fila da recepção, com o motivo.
//
// Injetados: event ({subject, payload_safe}), config (knobs/acoes), context ({agente_id}), call(), log().
// LGPD: só lê a conversa que o A0 armou; log e notas sem número da carteirinha nem dado do paciente.

var subject = event.subject || {};
var payloadSafe = event.payload_safe || {};
var selfId = String(context.agente_id || '');
var conversaId = subject.conversa_id ? String(subject.conversa_id) : null;
if (!conversaId) throw new Error('evento sem conversa_id — leitura não aplicável');

var fila = config.fila_recepcao || 'recepcao';
var esperaSeg = Number(config.espera_seg) || 12;
var tzOffset = config.tz_offset || '-03:00';
var maxMensagens = 4;
var tentativasResultado = Number(config.tentativas_resultado) || 3;   // cada uma espera até espera_seg no interacoes

// --- helpers -----------------------------------------------------------------

function unwrap(r) { var b = (r && r.body) ? r.body : r; return (b && b.data !== undefined) ? b.data : b; }
function lista(r) {
  var d = unwrap(r);
  if (!d) return [];
  if (d.length !== undefined) return d;
  if (d.items && d.items.length !== undefined) return d.items;
  return [];
}
function falhou(r) { return !r || r.ok === false; }

// O contexto que o A0 gravou na inscrição (o item da venda do pedido).
function meuContexto() {
  var obs = payloadSafe.observadores || [];
  for (var i = 0; i < obs.length; i++) {
    if (obs[i] && obs[i].tipo === 'bot' && String(obs[i].id) === selfId) return obs[i].contexto || {};
  }
  return {};
}

function pararDeAcompanhar() {
  call('desinscrever_observador', { conversa_id: conversaId, observador_tipo: 'bot', observador_id: selfId });
}

// Motivo = texto FIXO deste roteiro (nunca dado do paciente).
function paraRecepcao(motivo) {
  var nota = 'Carteirinha pedida pelo WhatsApp: ' + motivo + ' Confira a conversa e, se for o caso, cadastre à mão.';
  var r = call('transferir_fila', { conversa_id: conversaId, fila: fila, nota: nota });
  if (falhou(r)) call('comentar', { conversa_id: conversaId, conteudo: nota });
  log('passado para a recepção: ' + motivo);
  return { status: 'recepcao', motivo: motivo };
}

function hojeNaClinica() {
  var m = /^([+-])(\d{2}):(\d{2})$/.exec(tzOffset);
  var min = m ? (m[1] === '-' ? -1 : 1) * (Number(m[2]) * 60 + Number(m[3])) : -180;
  return new Date(Date.now() + min * 60000).toISOString().slice(0, 10);
}

function doisDig(n) { return (n < 10 ? '0' : '') + n; }
function diasNoMes(a, m) { return new Date(Date.UTC(a, m, 0)).getUTCDate(); }
function ano4(a) { a = Number(a); return a < 100 ? 2000 + a : a; }
function montarData(a, m, d) {
  a = ano4(a); m = Number(m);
  if (!(m >= 1 && m <= 12) || a < 2000 || a > 2100) return null;
  var ultimo = diasNoMes(a, m);
  d = (d === null) ? ultimo : Number(d);
  if (!(d >= 1 && d <= ultimo)) return null;
  return a + '-' + doisDig(m) + '-' + doisDig(d);
}
var MESES = { jan: 1, fev: 2, mar: 3, abr: 4, mai: 5, jun: 6, jul: 7, ago: 8, set: 9, out: 10, nov: 11, dez: 12 };

// Validade como vem impressa/escrita → AAAA-MM-DD. Só mês/ano = último dia do mês.
function lerValidade(txt) {
  var s = String(txt || '').trim().toLowerCase();
  if (!s) return null;
  var m;
  if ((m = /^(\d{4})-(\d{1,2})-(\d{1,2})$/.exec(s))) return montarData(m[1], m[2], m[3]);
  if ((m = /^(\d{1,2})\s*[\/.\-]\s*(\d{1,2})\s*[\/.\-]\s*(\d{2}|\d{4})$/.exec(s))) return montarData(m[3], m[2], m[1]);
  if ((m = /^(\d{1,2})\s*[\/.\-]\s*(\d{2}|\d{4})$/.exec(s))) return montarData(m[2], m[1], null);
  if ((m = /^([a-zç]{3})[a-zç]*\.?\s*(?:[\/.\-]|de)?\s*(\d{2}|\d{4})$/.exec(s)) && MESES[m[1]]) return montarData(m[2], MESES[m[1]], null);
  return null;
}

function semAcento(s) {
  s = String(s || '').toLowerCase();
  try { s = s.normalize('NFD').replace(/[̀-ͯ]/g, ''); } catch (e) { /* sem normalize: segue */ }
  return s;
}
var GENERICAS = { saude: 1, plano: 1, planos: 1, assistencia: 1, medica: 1, medico: 1, seguro: 1, seguros: 1,
  cooperativa: 1, trabalho: 1, operadora: 1, convenio: 1, servicos: 1, brasil: 1 };
function palavras(s) {
  var out = {}, ws = semAcento(s).split(/[^a-z0-9]+/);
  for (var i = 0; i < ws.length; i++) if (ws[i].length >= 4 && !GENERICAS[ws[i]]) out[ws[i]] = 1;
  return out;
}
// Operadora lida × convênio do pedido: diverge se não há palavra significativa em comum.
function operadoraDiverge(lida, doPedido) {
  if (!lida || !doPedido) return false;
  var a = palavras(lida), b = palavras(doPedido), temA = false;
  for (var w in a) { temA = true; if (b[w]) return false; }
  return temA && Object.keys(b).length > 0;
}

// Item do pedido na fila de autorizações (pendente ou já concluído).
function itemDoPedido(itemId) {
  var abas = ['pendentes', 'concluidos'];
  for (var i = 0; i < abas.length; i++) {
    var r = call('buscar_autorizacao_item', { aba: abas[i], item_id: itemId });
    if (falhou(r)) continue;
    var itens = lista(r);
    if (itens.length && itens[0]) return itens[0];
  }
  return null;
}

// --- 1) de quem é e qual convênio foi pedido -----------------------------------

var itemId = meuContexto().venda_item_id;
if (!itemId) return paraRecepcao('não achei o pedido ligado a esta conversa.');
var item = itemDoPedido(String(itemId));
if (!item || !item.convenio_id || !item.cliente_id) return paraRecepcao('não achei o convênio do pedido.');
var clienteId = String(item.cliente_id);
var convenioId = String(item.convenio_id);
if (subject.cliente_id && String(subject.cliente_id) !== clienteId) {
  return paraRecepcao('a conversa não é do paciente do pedido.');
}

// Já tem pedido pendente para este convênio (ex.: veio pelo link)? Não duplica.
var pendentes = lista(call('listar_solicitacoes_cliente', { cliente_id: clienteId, status: 'pendente' }));
for (var k = 0; k < pendentes.length; k++) {
  if (pendentes[k] && String(pendentes[k].convenio_id) === convenioId) {
    call('comentar', { conversa_id: conversaId,
      conteudo: 'Carteirinha pedida pelo WhatsApp: já há uma solicitação pendente deste convênio para a recepção aprovar.' });
    pararDeAcompanhar();
    return { status: 'ja_pendente' };
  }
}

// --- 2) o que o paciente mandou desde a última mensagem da clínica --------------

var msgs = lista(call('ler_conversa', { conversa_id: conversaId }));   // mais nova primeiro
var imagens = [], textos = [];
for (var i = 0; i < msgs.length; i++) {
  var m = msgs[i];
  if (!m) continue;
  if (m.direction !== 'in') break;
  if (m.apagada) continue;
  var ehImagem = m.tipo === 'image' || String(m.mime_type || '').indexOf('image/') === 0;
  if (ehImagem && m.midia_ref && !m.midia_expirada) imagens.push(String(m.id));
  else if ((m.tipo || 'text') === 'text' && String(m.conteudo || '').trim()) textos.push(String(m.id));
}
var porFoto = imagens.length > 0;
var ids = (porFoto ? imagens : textos).slice(0, maxMensagens).reverse();   // ordem em que chegaram
if (!ids.length) return paraRecepcao('o paciente respondeu sem foto nem texto que dê para ler.');

// --- 3) leitura (a mesma do botão "Extrair carteirinha") --------------------------

var r = call('extrair_carteirinha', { conversa_id: conversaId, mensagem_ids: ids, espera_max_seg: esperaSeg });
if (falhou(r)) return paraRecepcao('a leitura automática falhou.');
var x = unwrap(r) || {};
// A IA pode levar mais que a espera do extrair (homolog: ~18 s no texto): busca o resultado algumas vezes,
// cada uma esperando no interacoes. 404 = ainda processando.
for (var t = 0; t < tentativasResultado && x.status === 'processing' && x.correlation_id; t++) {
  var r2 = call('resultado_carteirinha', { conversa_id: conversaId, correlation_id: x.correlation_id, espera_max_seg: esperaSeg });
  if (!falhou(r2)) x = unwrap(r2) || x;
}
if (x.status !== 'ok' || !x.output) {
  return paraRecepcao(x.status === 'processing' ? 'a leitura automática não terminou a tempo.' : 'a leitura automática falhou.');
}
var o = x.output;
if (o.is_carteirinha === false) {
  return paraRecepcao(porFoto ? 'a foto não parece ser de uma carteirinha.' : 'a mensagem não traz os dados da carteirinha.');
}
var numero = String(o.numero_carteirinha || '').trim();
if (numero.length < 3 || numero.length > 64) return paraRecepcao('não deu para ler o número da carteirinha.');
var validade = lerValidade(o.validade);
if (!validade) return paraRecepcao('não deu para ler a validade (ou a carteirinha não traz validade).');
if (validade < hojeNaClinica()) return paraRecepcao('a carteirinha enviada está vencida.');

// --- 4) solicitação para a recepção aprovar ---------------------------------------

var atuais = lista(call('listar_convenios_cliente', { cliente_id: clienteId }));
var alvo = null;
for (var j = 0; j < atuais.length; j++) {
  var v = atuais[j];
  if (v && String(v.convenio_id) === convenioId && String(v.cliente_id) === clienteId && v.ativo !== false) { alvo = v; break; }
}

var obs = 'Lida pela IA na resposta do paciente no WhatsApp (' + (porFoto ? 'foto' : 'texto') + '). Confiança: '
  + ({ alta: 'alta', media: 'média', baixa: 'baixa' }[o.confianca_geral] || 'não informada') + '.';
var incertos = (o.campos_baixa_confianca || []).filter(function (c) {
  return c === 'numero_carteirinha' || c === 'validade' || c === 'plano' || c === 'operadora';
});
if (incertos.length) {
  var rotulo = { numero_carteirinha: 'número', validade: 'validade', plano: 'plano', operadora: 'operadora' };
  obs += ' Conferir: ' + incertos.map(function (c) { return rotulo[c]; }).join(', ') + '.';
}
if (operadoraDiverge(o.operadora, item.convenio_nome)) {
  obs += ' Atenção: a operadora lida (' + String(o.operadora).slice(0, 60) + ') não parece ser a do pedido ('
    + String(item.convenio_nome).slice(0, 60) + ').';
}

var solicitacao = {
  cliente_id: clienteId,
  tipo: alvo ? 'alterar' : 'adicionar',
  convenio_id: convenioId,
  numero: numero,
  validade: validade,
  origem: 'agente',
  observacao: obs
};
if (alvo) solicitacao.cliente_convenio_id = String(alvo.id);
if (o.plano && String(o.plano).trim()) solicitacao.plano = String(o.plano).trim().slice(0, 120);

var criada = call('criar_solicitacao_convenio', solicitacao);
if (falhou(criada)) return paraRecepcao('não consegui criar a solicitação (HTTP ' + (criada ? criada.status_code : '?') + ').');

call('comentar', { conversa_id: conversaId,
  conteudo: 'Carteirinha lida pela IA: solicitação criada para a recepção aprovar (Clientes → Solicitações de convênio).' });
pararDeAcompanhar();
log('solicitação de convênio criada (' + solicitacao.tipo + ', ' + (porFoto ? 'foto' : 'texto') + ')');
return { status: 'solicitacao_criada', tipo: solicitacao.tipo, por: porFoto ? 'foto' : 'texto',
  confianca: o.confianca_geral || null, divergencia_operadora: operadoraDiverge(o.operadora, item.convenio_nome) };
